bool simplify(String x, String n) {
  List<String> xParts = x.split("/");
  List<String> nParts = n.split("/");

  int a = int.parse(xParts[0]);
  int b = int.parse(xParts[1]);
  int c = int.parse(nParts[0]);
  int d = int.parse(nParts[1]);

  int numerator = a * c;
  int denom = b * d;

